&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Mal&#233;diction est &#233;galement le nom d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Sort-Mal&#233;diction.html&quot; title=&quot;Mal&#233;diction&quot;&gt;sort&lt;/a&gt;. Voir aussi la &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;diction-(Capacit&#233;).html&quot; title=&quot;Mal&#233;diction (Sur)&quot;&gt;capacit&#233; de monstre&lt;/a&gt; de m&#234;me nom.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;
Des voleurs insouciants pillant une tombe, des aventuriers ivres insultant un puissant magicien, des explorateurs t&#233;m&#233;raires mettant la main sur d’antiques &#233;p&#233;es, tous peuvent subir une mal&#233;diction. Ces afflictions magiques ont des effets vari&#233;s, d’un simple malus sur certains jets &#224; une transformation en crapaud de l’infortun&#233;. Certaines peuvent m&#234;me provoquer la d&#233;composition de la victime, qui ne laissera derri&#232;re elle qu’un peu de poussi&#232;re.&lt;br /&gt;&lt;br /&gt;La plupart du temps, les mal&#233;dictions ne s’effacent pas avec quelques &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt;. Seule la magie peut les gu&#233;rir, &#224; l’aide de sorts comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;livrance-Des-Mal&#233;dictions.html&quot; title=&quot;D&#233;livrance des mal&#233;dictions&quot;&gt;d&#233;livrance des mal&#233;dictions&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Annulation-Denchantement.html&quot; title=&quot;Annulation d&amp;#39;enchantement&quot;&gt;annulation d’enchantement&lt;/a&gt;&lt;/i&gt;. &lt;br /&gt;&lt;br /&gt;Alors que certaines d&#233;t&#233;riorent lentement leur victime, d’autres infligent un malus fixe &#224; partir du moment o&#249; on les contracte, un malus qui s’att&#233;nuera ni ne grandira. Il existe &#233;galement des objets magiques dont les effets sont similaires &#224; ceux d’une mal&#233;diction (voir &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Maudits.html&quot; title=&quot;Les objets maudits&quot;&gt;objets maudits&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;Les exemples suivants pr&#233;sentent quelques-unes des mal&#233;dictions existantes. Pour plus d&#39;informations sur le format des descriptions, voir &lt;a class=&quot;pagelink&quot; href=&quot;Afflictions.html&quot; title=&quot;Les afflictions&quot;&gt;les afflictions&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Malchance&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; mal&#233;diction ; &lt;b&gt;JdS&lt;/b&gt; Volont&#233; (DD 20), annule, pas de JS pour &#233;viter les effets&lt;/li&gt;&lt;li&gt;&lt;b&gt;Fr&#233;quence&lt;/b&gt; 1/heure&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; doit relancer n’importe quel jet de d&#233;s, au choix du MJ, et garder le plus mauvais r&#233;sultat&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Mal&#233;diction de Lycaon&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; mal&#233;diction, blessure ; &lt;b&gt;JdS&lt;/b&gt; Vigueur (DD 15), annule ; Volont&#233; (DD 15) pour &#233;viter les effets&lt;/li&gt;&lt;li&gt;&lt;b&gt;Incubation&lt;/b&gt; la prochaine pleine lune ; &lt;b&gt;Fr&#233;quence&lt;/b&gt; la nuit de chaque pleine lune ou quand la cible est bless&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; la cible se transforme en loup et passe sous le contr&#244;le du MJ jusqu’au prochain lever du soleil&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Mal&#233;diction des corbeaux&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MALEDICTIONDESCORBEAUX&quot; href=&quot;#MALEDICTIONDESCORBEAUX&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;script&gt;
	$(function(){
		$(&#39;.CSU1&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Cities of Golarion/Cit&#233;s de Golarion)&quot;);
		$(&#39;.CSU2&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Lost Cities of Golarion/Cit&#233;s perdues de Golarion)&quot;);
		$(&#39;.CSU3&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Dungeons of Golarion/Donjons de Golarion)&quot;);
		$(&#39;.CSU4&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Guide to Korvosa/Guide de Korvosa)&quot;);
		$(&#39;.CSU5&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (The Worldwound/Guide de la Plaie du monde)&quot;);
		$(&#39;.CSU6&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Isles of the Shackles/Guide des Cha&#238;nes)&quot;);
		$(&#39;.CSU7&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Guide to the River Kingdoms/Guide des Royaumes fluviaux)&quot;);
		$(&#39;.CSU8&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Dark Markets - A Guide to Katapesh/Guide du Katapesh)&quot;);
		$(&#39;.CSU9&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Guide to Darkmoon Vale/Guide du Val de Sombrelune)&quot;);
		$(&#39;.CSU10&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Irrisen - Land of Eternal Winter/Irrisen, Pays de l&#39;hiver &#233;ternel)&quot;);
		$(&#39;.CSU11&#39;).attr(&#39;title&#39;, &quot;Source : Courts suppl&#233;ments univers (Ships of the Inner Sea/Navires de la mer Int&#233;rieure)&quot;)
	});
&lt;/script&gt;
&lt;a class=&quot;CSU10&quot; href=&quot;/Wiki/Pathfinder-RPG.Courts suppl&#233;ments univers (Contenu).ashx#10&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/LogoCSU.jpg&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; mal&#233;diction ; &lt;b&gt;JdS&lt;/b&gt; Volont&#233; (DD 13)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet initial&lt;/b&gt; la victime est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paniqu&#233;.html&quot; title=&quot;Paniqu&#233;&quot;&gt;paniqu&#233;e&lt;/a&gt; pendant 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; ; &lt;b&gt;Effet secondaire&lt;/b&gt; la victime est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secou&#233;e&lt;/a&gt; de fa&#231;on permanente&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Bien que nombreux soient les gens qui rient de la superstition du nord selon laquelle ces oiseaux sont des messagers de la mort, certains vols de corbeaux d&#233;gagent r&#233;ellement une &#233;nergie malveillante qui leur est transmise par une combinaison du froid surnaturel et de la magie mal&#233;fique qui recouvre la nation glac&#233;e. Ainsi, si des voyageurs se trouvent &#224; 6 m&#232;tres d’un vol de corbeaux poss&#233;d&#233;s par cette &#233;nergie, ou s’ils sont survol&#233;s par de tels corbeaux, l’&#233;nergie mal&#233;fique qui a impr&#233;gn&#233; les ailes des oiseaux infecte les infortun&#233;s. Les cr&#233;atures affect&#233;es doivent alors r&#233;ussir un jet de sauvegarde de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13 ou devenir victimes de la mal&#233;diction. La mal&#233;diction des corbeaux peut &#234;tre lev&#233;e &#224; l’aide d’un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;livrance-Des-Mal&#233;dictions.html&quot; title=&quot;D&#233;livrance des mal&#233;dictions&quot;&gt;d&#233;livrance des mal&#233;dictions&lt;/a&gt;&lt;/i&gt; ou une magie similaire.
&lt;/div&gt;
&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;&lt;/td&gt;&lt;td &lt;width=&quot;49%&quot;&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Mal&#233;diction du vieillard&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; mal&#233;diction ; &lt;b&gt;JdS&lt;/b&gt; Volont&#233; (DD 17)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Fr&#233;quence&lt;/b&gt; 1/jour&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; vieillit d’un an&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;M&#233;tamorphose funeste&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; mal&#233;diction, sort ; &lt;b&gt;JdS&lt;/b&gt; Vigueur (DD 17), annule ; Volont&#233; (DD 17), partiel&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; transforme la cible en l&#233;zard (voir la description du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose-Funeste.html&quot; title=&quot;M&#233;tamorphose funeste&quot;&gt;m&#233;tamorphose funeste&lt;/a&gt;&lt;/i&gt;)&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Pi&#232;ge maudit&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; mal&#233;diction, pi&#232;ge, sort ; &lt;b&gt;JdS&lt;/b&gt; Volont&#233; (DD 14)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; malus de -6 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Putr&#233;faction de momie&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Type&lt;/b&gt; mal&#233;diction, maladie blessure ; &lt;b&gt;JdS&lt;/b&gt; Vigueur (DD 16)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Incubation&lt;/b&gt; 1 minute ; &lt;b&gt;Fr&#233;quence&lt;/b&gt; 1/jour&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; 1d6 points d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissement temporaire&lt;/a&gt; de la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; et du &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; ; &lt;b&gt;Gu&#233;rison&lt;/b&gt; lancement r&#233;ussi de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;livrance-Des-Mal&#233;dictions.html&quot; title=&quot;D&#233;livrance des mal&#233;dictions&quot;&gt;d&#233;livrance des mal&#233;dictions&lt;/a&gt;&lt;/i&gt; et de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Des-Maladies.html&quot; title=&quot;Gu&#233;rison des maladies&quot;&gt;gu&#233;rison des maladies&lt;/a&gt;&lt;/i&gt; &#224; une minute d’intervalle l’un de l’autre&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
